'use strict';
// YouTube Shorts grid on Home and Channel, generated by scripts/sync-shorts.js from youtube-shorts.js.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom');
const S=require('../youtube-shorts'),{markup}=require('../scripts/sync-shorts'),root=path.join(__dirname,'..');let count=0;
async function test(name,fn){await fn();count++;console.log('ok - '+name);}
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const PAGES=['index.html','channel.html'];
const EXPECTED=['ap-y7-83m4E','vhKMcF7J-wY','5X0FzhK5aKs','L682RKj82Nw','gSOsZp-KYp0','kBH7lrqXLfI','oDocZtVtS80','gcMUTylpG_0'];
const dom=f=>new JSDOM(read(f)).window.document;
(async()=>{
 await test('data lists every public, embeddable Short once, featured ap-y7-83m4E first, with real titles and dates',()=>{
  assert.equal(S.featured,'ap-y7-83m4E');assert.deepEqual(S.shorts.map(s=>s.id),EXPECTED);assert.equal(new Set(S.shorts.map(s=>s.id)).size,8);
  for(const s of S.shorts){assert(/^[A-Za-z0-9_-]{11}$/.test(s.id));assert(s.title.length>5&&!/coming soon|placeholder/i.test(s.title),s.id);
   assert(/^2026-11-\d{2}$/.test(s.published));assert(['@danielmotter62','@DanielEMotter'].includes(s.channel));}
  assert.equal(S.shorts.find(s=>s.id==='oDocZtVtS80').title,'Day one of Paying off 50k of Debt');
  assert.equal(S.shorts.find(s=>s.id==='gcMUTylpG_0').title,'Day 2 of Becoming Debt Free | How to Get Out of Debt FAST ($50K Debt Payoff Journey)');
 });
 await test('Home and Channel show the same Shorts grid, generated from the data (no stale markup)',()=>{
  for(const f of PAGES){const s=read(f),m=s.match(/<!-- shorts:start -->\n([\s\S]*?)\n  <!-- shorts:end -->/);assert(m,f);assert.equal(m[1],markup(),f+' is stale: run node scripts/sync-shorts.js');
   assert.equal((s.match(/<!-- shorts:start -->/g)||[]).length,1,f);}
 });
 await test('featured Short is a lazy 9:16 iframe; the other Shorts are lite thumbnails that link to the real Short',()=>{
  for(const f of PAGES){const d=dom(f),items=[...d.querySelectorAll('#shorts .shorts > figure.short-item')];assert.equal(items.length,8,f);
   const fr=items[0].querySelector('.short > iframe');assert.equal(fr.getAttribute('src'),'https://www.youtube.com/embed/ap-y7-83m4E');assert.equal(fr.getAttribute('loading'),'lazy');assert(fr.hasAttribute('allowfullscreen'));
   assert.equal(d.querySelectorAll('#shorts iframe').length,1,f+' only the featured Short loads an iframe up front');
   items.slice(1).forEach((it,i)=>{const id=EXPECTED[i+1],a=it.querySelector('.short.lite > a.short-play');assert(a,f+' '+id);
    assert.equal(a.getAttribute('href'),'https://www.youtube.com/shorts/'+id);assert.equal(a.dataset.shortId,id);assert.equal(a.getAttribute('rel'),'noopener');
    const img=a.querySelector('img');assert.equal(img.getAttribute('src'),'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg');assert.equal(img.getAttribute('loading'),'lazy');assert.equal(img.getAttribute('alt'),'');
    assert(a.getAttribute('aria-label').endsWith(S.shorts[i+1].title));});
   items.forEach((it,i)=>assert(it.querySelector('figcaption').textContent.endsWith(S.shorts[i].title),f));
   assert(!d.querySelector('#shorts .short.soon'),f+' Coming soon Short slot should be replaced');}
 });
 await test('long-form featured video GZ6XsM35GkQ and its Coming soon slots are unchanged',()=>{
  for(const f of PAGES){const d=dom(f),v=[...d.querySelectorAll('.videos > article.video')];assert.equal(v.length,3,f);
   assert.equal(v[0].querySelector('iframe').getAttribute('src'),'https://www.youtube.com/embed/GZ6XsM35GkQ');assert.equal(v.slice(1).filter(x=>x.querySelector('h3').textContent==='Coming soon').length,2);}
 });
 await test('shorts.css keeps 9:16 tiles, red accent and a responsive 2/3/4-column grid; pages load stamped assets',()=>{
  const css=read('shorts.css');assert(/\.shorts\{display:grid;grid-template-columns:repeat\(2,minmax\(0,1fr\)\)/.test(css));
  assert(/min-width:640px\)\{\.shorts\{grid-template-columns:repeat\(3/.test(css)&&/min-width:900px\)\{\.shorts\{grid-template-columns:repeat\(4/.test(css));
  assert(/\.short-icon\{[^}]*background:var\(--accent\)/.test(css));
  for(const f of PAGES){const s=read(f);assert(/\.short\{[^}]*aspect-ratio:9\/16/.test(s),f);assert(/<link rel="stylesheet" href="shorts\.css\?v=[0-9a-f]{10}">/.test(s),f);assert(/<script src="shorts-lite\.js\?v=[0-9a-f]{10}"><\/script>/.test(s),f);}
 });
 await test('clicking a lite thumbnail swaps in the embed iframe without innerHTML; modified clicks open YouTube',()=>{
  const js=read('shorts-lite.js');assert(!/innerHTML|outerHTML|insertAdjacentHTML/.test(js.replace(/\/\*[\s\S]*?\*\//g,'')));
  const w=new JSDOM(read('channel.html'),{runScripts:'outside-only'}).window;w.eval(js);
  const a=w.document.querySelector('a.short-play[data-short-id="L682RKj82Nw"]'),box=a.parentNode;
  const mod=new w.MouseEvent('click',{bubbles:true,cancelable:true,ctrlKey:true});a.dispatchEvent(mod);assert(!mod.defaultPrevented);assert(box.contains(a));
  const ev=new w.MouseEvent('click',{bubbles:true,cancelable:true});a.dispatchEvent(ev);assert(ev.defaultPrevented);
  const fr=box.querySelector('iframe');assert.equal(fr.getAttribute('src'),'https://www.youtube.com/embed/L682RKj82Nw?autoplay=1');assert.equal(fr.getAttribute('title'),'Day 6 of paying of 50k in debt.');
  assert(fr.hasAttribute('allowfullscreen'));assert(!box.classList.contains('lite'));assert.equal(w.document.querySelectorAll('#shorts iframe').length,2);
  const bad=w.document.querySelector('a.short-play[data-short-id="gcMUTylpG_0"]');bad.setAttribute('data-short-id','x"><script>');const e2=new w.MouseEvent('click',{bubbles:true,cancelable:true});bad.dispatchEvent(e2);assert(!e2.defaultPrevented);
  w.close();
 });
 console.log(count+' Shorts tests passed');
})().catch(e=>{console.error(e);process.exitCode=1;});
